class Solution:
    def decodeString(self, s: str) -> str:
        stack = []
        for ch in s:
            if ch != "]":
                stack.append(ch)
                continue
            part = []
            while stack[-1] != "[":
                part.append(stack.pop())
            stack.pop()
            digits = []
            while stack and stack[-1].isdigit():
                digits.append(stack.pop())
            count = int("".join(reversed(digits)))
            stack.extend(reversed(part * count))
        return "".join(stack)

