class Solution:
    def decodeString(self, s: str) -> str:
        stack = []
        current = []
        number = 0
        for ch in s:
            if ch.isdigit():
                number = number * 10 + int(ch)
            elif ch == "[":
                stack.append((current, number))
                current = []
                number = 0
            elif ch == "]":
                prev, count = stack.pop()
                # Complete this frame and restore the outer string.
                current = prev + current * count
            else:
                current.append(ch)
        return "".join(current)

